<template>
  <div class="profile">
    <ProfileHeaderModeration
      :title="publication?.title_moderation"
      :uniqueCode="publication?.id"
      :phone="publication?.phone || '+7 (000) 000-00-00'"
      :address="
        publication?.ads_parameter?.place_inspection ||
        'Ростовская область; Ростов-на-Дону; Ворошиловский р-н'
      "
      :date="publication?.updated_at"
      :moderator="publication?.ads_parameter?.username"
      :backIcon="backIcon"
      :goBack="goBack"
    />

    <!-- Скроллируемая часть -->
    <div class="profile__wrapper">
      <div class="publication-content">
        <div class="publication-info">
          <!-- Фото объявления -->
          <img
            :src="publicationBlock.ads_photo"
            alt="Фото объявления"
            class="publication-photo"
          />

          <!-- Контейнер для информации -->
          <div class="publication-details">
            <!-- Заголовок объявления -->
            <h4 class="publication-title">
              {{ publicationBlock.title_moderation }}
            </h4>

            <!-- Цена объявления -->
            <p class="publication-price">{{ publicationBlock.price }}</p>

            <div class="seller-info">
              <!-- Фото профиля продавца -->
              <img
                :src="publicationBlock.avatar"
                alt="Фото профиля"
                class="seller-avatar"
              />

              <div class="seller-details">
                <!-- Имя продавца и номер телефона -->
                <p class="seller-name">
                  {{
                    `${publicationBlock.username}` +
                    ` [${publicationBlock.phone}]`
                  }}
                </p>

                <!-- Дата регистрации продавца -->
                <p class="seller-registered">
                  {{ formatDate(publicationBlock.created_at) }}
                </p>
              </div>
            </div>
          </div>
        </div>
        <div v-if="publicationBlock.content" class="violation-block__text">
          {{ publicationBlock.content }}
        </div>
      </div>
      <div class="violation-form">
        <h3 class="violation-form__title">
          {{ moderationTitle }}
        </h3>

        <div
          v-for="(item, key) in violations"
          :key="key"
          class="violation-block"
        >
          <div class="violation-block__info">
            <CheckboxUI
              v-if="item.label !== 'claim_reason'"
              v-model="item.enabled"
            />
            <p class="violation-block__title">{{ item.label }}</p>
          </div>
          <div class="violation-block__text">{{ item?.content || 'wewe' }}</div>
          <div class="violation-block__dropdown" v-if="item.enabled">
            <AdsDropdown
              :options="dropdownOptions"
              placeholder="Выберите причину"
              @updateSort="(val) => (item.reason = val)"
            />
          </div>
        </div>

        <div v-if="photosWithViolations?.label" class="divider"></div>

        <div class="photo-grid">
          <div
            v-for="photo in photosWithViolations"
            :key="photo.id"
            class="photo-block"
          >
            <img :src="photo.url" class="photo-block__img" />
            <div class="photo-block__checkbox">
              <CheckboxUI v-model="photo.enabled" />
            </div>
            <div class="photo-block__dropdown" v-if="photo.enabled">
              <AdsDropdown
                :options="dropdownOptions"
                placeholder="Выберите причину"
                @updateSort="(val) => (photo.reason = val)"
              />
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="divider"></div>
    <div class="violation-form__actions">
      <template
        v-if="route.params.type === 'review' || route.params.type === 'comment'"
      >
        <button @click="approvePublication" class="btn approve">
          Разрешить
        </button>
        <button @click="rejectPublication" class="btn reject">Отклонить</button>
      </template>

      <template v-else-if="route.params.type === 'claim'">
        <button @click="rejectPublication" class="btn reject">Отклонить</button>
        <button @click="removeFromPublication" class="btn remove">
          Снять с публикации
        </button>
        <button @click="banSeller" class="btn ban">
          Заблокировать продавца
        </button>
      </template>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import {
  updateAction,
  getClaimById,
  getCommentById,
  getReviewById,
} from '@/services/apiClient';
import { getImageUrl } from '@/services/imageUtils';
import { format } from 'date-fns';
import backIcon from '@/assets/icons/back-wide.svg';
import photoPlaceholder from '@/assets/icons/placeholder.png';
import avatarPlaceholder from '@/assets/icons/avatar-revers.svg';

import ProfileHeaderModeration from '@/components/UI/CustomProfileHeaderModeration.vue';
import CheckboxUI from '@/components/UI/CheckboxUINEW.vue';
import AdsDropdown from '@/components/AdsDropdown.vue';

const route = useRoute();
const router = useRouter();
const publication = ref(null);
const loading = ref(true);
const violations = ref([]);
const moderationTitle = ref('');

const publicationBlock = ref({
  ads_photo: '',
  title_moderation: '',
  price: '',
  avatar: '',
  username: '',
  phone: '',
  created_at: '',
  content: '',
});

const dropdownOptions = [
  { label: 'Нарушение законодательства (П. 2)', value: 'law_violation' },
  {
    label: 'Нарушение правил сервиса (П. 3)',
    value: 'service_rules_violation',
  },
  { label: 'Грубая лексика (П. 4)', value: 'offensive_language' },
  { label: 'Недостоверные данные (П. 5)', value: 'false_information' },
  { label: 'Мошенничество (П. 6)', value: 'fraud' },
  { label: 'Порнография (П. 7)', value: 'pornography' },
  { label: 'Другое', value: 'other' },
];

const photosWithViolations = ref([]);

const formatDate = (date) => {
  if (!date) return 'Не указана';
  return format(new Date(date), 'dd MMMM yyyy');
};

const collectAdminComment = () => {
  const fieldsComment = {};

  Object.entries(violations.value).forEach(([key, item]) => {
    if (item.enabled && item.reason) {
      fieldsComment[key] = item.reason;
    }
  });

  // Нарушения по фото
  photosWithViolations.value.forEach((photo) => {
    if (photo.enabled && photo.reason) {
      fieldsComment[`photo_${photo.id}`] = photo.reason;
    }
  });

  return fieldsComment;
};

const approvePublication = async () => {
  const formData = {
    is_cancelled: 0,
  };
  // нужен ли этот лог в проекте
  console.log('APPROVED DATA:', formData);
  const type = route.params.type;
  await updateAction(route.params.id, formData, type);
};

const rejectPublication = async () => {
  const formData = {
    is_cancelled: 1,
    admin_comment: {
      fields_comment: collectAdminComment(),
    },
  };
  // нужен ли этот лог в проекте
  console.log('REJECTED DATA:', formData);
  const type = route.params.type;
  await updateAction(route.params.id, formData, type);
};

const removeFromPublication = async () => {
  const formData = {
    action: 'remove_from_publication',
    admin_comment: {
      fields_comment: collectAdminComment(),
    },
  };
  // нужен ли этот лог в проекте
  console.log('REMOVE FROM PUBLICATION DATA:', formData);
};

const banSeller = async () => {
  const formData = {
    action: 'ban_seller',
    admin_comment: {
      fields_comment: collectAdminComment(),
    },
  };
  // нужен ли этот лог в проекте
  console.log('BAN SELLER DATA:', formData);
};

const mapPhotos = (photos = []) => {
  return photos.map((photo) => ({
    id: photo.id,
    title: photo.title,
    url: getImageUrl(photo.arr_title_size?.default, photoPlaceholder),
    enabled: false,
    reason: null,
  }));
};

const fetchPublicationData = async () => {
  try {
    const { type, id } = route.params;
    // нужен ли этот лог в проекте
    console.log('[fetchPublicationData] Параметры:', { type, id });

    let response = null;

    switch (type) {
      case 'review':
        moderationTitle.value = 'Подтвердите или отклоните публикацию отзыва';
        response = await getReviewById();
        photosWithViolations.value = mapPhotos(response?.photos);

        publicationBlock.value = {
          ads_photo: getImageUrl(
            response?.ads_photos?.[0]?.arr_title_size?.preview,
            photoPlaceholder
          ),
          title_moderation: response?.ads_title || 'Не указано',
          price: response?.ads_price || 'Цена не указана',
          avatar: getImageUrl(
            response?.user?.photo?.arr_title_size?.preview,
            avatarPlaceholder
          ),
          username: response?.user?.username || 'Имя не указано',
          phone: response?.user?.phone || '+7 (000) 000-00-00',
          created_at: response?.user?.created_at || null,
          content: null,
        };

        violations.value = [
          {
            key: 'review',
            label: 'Отзыв',
            enabled: false,
            reason: null,
            get content() {
              return response?.comment || 'Не указано';
            },
          },
        ];
        break;

      case 'comment':
        moderationTitle.value = 'Подтвердите или отклоните ответ на отзыв';
        response = await getCommentById(id);
        photosWithViolations.value = mapPhotos(response?.photos);

        publicationBlock.value = {
          ads_photo: getImageUrl(
            response?.ads_photos?.[0]?.arr_title_size?.preview,
            photoPlaceholder
          ),
          title_moderation: response?.ads_title || 'Не указано',
          price: response?.ads_price || 'Цена не указана',
          avatar: getImageUrl(
            response?.user?.photo?.arr_title_size?.preview,
            avatarPlaceholder
          ),
          username: response?.user?.username || 'Имя не указано',
          phone: response?.user?.phone || '+7 (000) 000-00-00',
          created_at: response?.user?.created_at || null,
          content: 'Тут будет текст отзыва, который написал пользователь',
        };

        violations.value = [
          {
            key: 'comment',
            label: 'Ответ на отзыв',
            enabled: false,
            reason: null,
            get content() {
              return response?.comment || 'Не указано';
            },
          },
        ];
        break;

      case 'claim':
        moderationTitle.value = 'Рассмотрите жалобу';
        response = await getClaimById(id);
        photosWithViolations.value = mapPhotos(response?.photos);

        publicationBlock.value = {
          ads_photo: getImageUrl(
            response?.ads_photos?.[0]?.arr_title_size?.preview,
            photoPlaceholder
          ),
          title_moderation: response?.ads_title || 'Не указано',
          price: response?.ads_price || 'Цена не указана',
          avatar: getImageUrl(
            response?.user?.photo?.arr_title_size?.preview,
            avatarPlaceholder
          ),
          username: response?.user?.username || 'Имя не указано',
          phone: response?.user?.phone || '+7 (000) 000-00-00',
          created_at: response?.user?.created_at || null,
          content: null,
        };

        violations.value = [
          {
            key: 'claim_reason',
            label: 'Причина жалобы',
            enabled: false,
            reason: null,
            get content() {
              return response?.reason || 'Не указано';
            },
          },
          {
            key: 'claim_comment',
            label: 'Комментарий к жалобе',
            enabled: false,
            reason: null,
            get content() {
              return response?.comment || 'Не указано';
            },
          },
        ];
        break;

      default:
        console.warn('[fetchPublicationData] Неизвестный тип:', type);
    }

    publication.value = response;
    // нужен ли этот лог в проекте
    console.log(
      '[fetchPublicationData] Сформированные violations:',
      violations.value
    );
  } catch (error) {
    console.error('[fetchPublicationData] Ошибка при получении данных:', error);
    publication.value = null;
  } finally {
    loading.value = false;
  }
};

const goBack = () => {
  router.back();
};

onMounted(fetchPublicationData);
</script>

